CREATE TABLE IF NOT EXISTS users (userId INT AUTO_INCREMENT PRIMARY KEY, fullName VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL UNIQUE, passwordHash VARCHAR(255) NOT NULL, reminderLeadMinutes INT NOT NULL DEFAULT 30, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contacts (contactId INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(100), phone VARCHAR(20), notes TEXT, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX(userId), CONSTRAINT fk_contact_user FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS appointments (appointmentId INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, title VARCHAR(150) NOT NULL, contactId INT NULL, appointmentDate DATE NOT NULL, appointmentTime TIME NOT NULL, location VARCHAR(150), notes TEXT, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX idx_appointment_owner_date(userId,appointmentDate), INDEX(contactId), CONSTRAINT fk_appointment_user FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE CASCADE, CONSTRAINT fk_appointment_contact FOREIGN KEY(contactId) REFERENCES contacts(contactId) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS schedules (scheduleId INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, description VARCHAR(255) NOT NULL, objective VARCHAR(255), scheduleDate DATE NOT NULL, scheduleTime TIME, notes TEXT, INDEX(userId), CONSTRAINT fk_schedule_user FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks (taskId INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, title VARCHAR(150) NOT NULL, dueDate DATE NULL, isCompleted BOOLEAN NOT NULL DEFAULT FALSE, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX(userId), CONSTRAINT fk_task_user FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS delegate_access (delegateAccessId INT AUTO_INCREMENT PRIMARY KEY, ownerUserId INT NOT NULL, delegateUserId INT NOT NULL, permissionLevel ENUM('FreeBusyOnly','FullDetails') NOT NULL, grantedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_delegate(ownerUserId,delegateUserId), INDEX(delegateUserId), CONSTRAINT fk_da_owner FOREIGN KEY(ownerUserId) REFERENCES users(userId) ON DELETE CASCADE, CONSTRAINT fk_da_delegate FOREIGN KEY(delegateUserId) REFERENCES users(userId) ON DELETE CASCADE, CONSTRAINT chk_not_self CHECK(ownerUserId <> delegateUserId));
CREATE TABLE IF NOT EXISTS meeting_invitations (invitationId INT AUTO_INCREMENT PRIMARY KEY, appointmentId INT NOT NULL, inviterUserId INT NOT NULL, inviteeUserId INT NULL, inviteeEmail VARCHAR(100), status ENUM('Pending','Accepted','Declined') NOT NULL DEFAULT 'Pending', token CHAR(64) NOT NULL UNIQUE, sentAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, respondedAt DATETIME NULL, INDEX(inviteeUserId), INDEX(appointmentId), CONSTRAINT fk_inv_appointment FOREIGN KEY(appointmentId) REFERENCES appointments(appointmentId) ON DELETE CASCADE, CONSTRAINT fk_inv_inviter FOREIGN KEY(inviterUserId) REFERENCES users(userId) ON DELETE CASCADE, CONSTRAINT fk_inv_invitee FOREIGN KEY(inviteeUserId) REFERENCES users(userId) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reminders (reminderId INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, referenceType ENUM('Appointment','Task') NOT NULL, referenceId INT NOT NULL, leadTimeMinutes INT NOT NULL, status ENUM('Pending','Sent') NOT NULL DEFAULT 'Pending', sentAt DATETIME NULL, UNIQUE KEY uq_reminder(userId,referenceType,referenceId,leadTimeMinutes), INDEX(userId), CONSTRAINT fk_reminder_user FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notifications (notificationId INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, message VARCHAR(500) NOT NULL, link VARCHAR(255), isRead BOOLEAN NOT NULL DEFAULT FALSE, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(userId,isRead,createdAt), CONSTRAINT fk_notification_user FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE CASCADE);
